var a=`1088-halo-halo`;var n=`world-1088`;var s=`PH`;var t=`southeast-asia`;var o=8;var d=33;var l={en:`Halo-Halo`,ua:`Гало-гало`};var r={en:`Halo-Halo is a dish from Philippines prepared with red bean paste (anko), tapioca pearls, evaporated milk, sweetened condensed milk. This is a home-scale version with measured ingredients in the individual steps where they are used. Simplified halo-halo: specialty ube ice cream, nata de coco and jellies are unavailable, so the mixed dessert differs.`,ua:`Гало-гало, страва кухні країни Філіппіни, яку готують із таких продуктів: паста анко, кульки тапіоки, концентроване молоко без цукру, згущене молоко з цукром. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Спрощений гало-гало: немає морозива убе, ната-де-коко та окремих желе; десерт відрізнятиметься.`};var m=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`red-bean-paste-anko`,180,`g`]]},{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`tapioca-pearls`,100,`g`],[`water`,550,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`evaporated-milk`,280,`ml`],[`sweetened-condensed-milk`,140,`g`]]},{en:`Arrange thoroughly cooked tapioca, prepared sweet bean paste, fruit, clean crushed ice and syrup in chilled glasses; do not add uncooked dry pearls.`,ua:`Розкладіть повністю зварену тапіоку, солодку бобову пасту, фрукти, чистий колотий лід і сироп в охолоджені склянки; не додавайте сухі перлини тапіоки.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`banana`,2,`pcs`],[`jackfruit`,220,`g`],[`canned-lychee`,160,`g`],[`ice-cubes`,500,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`whipping-cream`,250,`ml`]]}];var c={slug:a,id:n,country:`PH`,region:t,servings:8,minutes:33,title:l,text:r,steps:m};export{s as country,c as default,n as id,d as minutes,t as region,o as servings,a as slug,m as steps,r as text,l as title};